/* libstdc++ _Hash_bytes (Murmur64A) — matches std::hash<std::string> */
static uint64_t murmur_hash(const unsigned char* data, size_t len) {
    const uint64_t m = 0xc6a4a7935bd1e995ULL, r = 47, mask = ~0ULL;
    uint64_t h = 0xc70f6907ULL ^ ((len * m) & mask);
    size_t nb = len & ~(size_t)7;
    for (size_t i = 0; i < nb; i += 8) {
        uint64_t k; memcpy(&k, data + i, 8);
        k = (k * m) & mask; k ^= k >> r; k = (k * m) & mask;
        h ^= k; h = (h * m) & mask;
    }
    const unsigned char* t = data + nb; size_t tl = len - nb;
    switch (tl) {
    case 7: h ^= (uint64_t)t[6] << 48;
    case 6: h ^= (uint64_t)t[5] << 40;
    case 5: h ^= (uint64_t)t[4] << 32;
